// The center follows the x intersection in the current Omnixa outline.
const CORE_PATH = "M 475.3 69.7 L 481.3 75.7 L 475.3 81.7 L 469.3 75.7 Z"

export function Wordmark(
  props: Pick<ComponentProps<"svg">, "class" | "onAnimationEnd"> & {
    fade?: boolean
    muted?: boolean
    outline?: boolean
  },
) {
  const mask = createUniqueId()
  const gradient = createUniqueId()

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 720 129"
      fill="none"
      role="img"
      aria-label="Omnixa"
      onAnimationEnd={props.onAnimationEnd}
      classList={{ [props.class ?? ""]: !!props.class, "overflow-visible": props.outline }}
    >
      <g opacity={props.muted === false ? 1 : 0.6} mask={props.fade === false ? undefined : `url(#${mask})`}>
        <path
          d={LETTER_PATH}
          pathLength={props.outline ? 1 : undefined}
          fill={props.outline ? "none" : "currentColor"}
          stroke={props.outline ? "currentColor" : undefined}
          stroke-width={props.outline ? 1 : undefined}
          vector-effect={props.outline ? "non-scaling-stroke" : undefined}
        />
        <path
          d={CORE_PATH}
          pathLength={props.outline ? 1 : undefined}
          fill={props.outline ? "none" : "var(--omnxa-core-color, var(--v2-icon-brand-core, currentColor))"}
          stroke={props.outline ? "currentColor" : undefined}
          stroke-width={props.outline ? 1 : undefined}
          vector-effect={props.outline ? "non-scaling-stroke" : undefined}
        />
      </g>
      <defs>
        <mask id={mask} style="mask-type:alpha" maskUnits="userSpaceOnUse" x="0" y="0" width="720" height="129">
          <rect width="720" height="129" fill={`url(#${gradient})`} />
        </mask>
        <linearGradient id={gradient} x1="360" y1="0" x2="360" y2="129" gradientUnits="userSpaceOnUse">
          <stop stop-color="white" stop-opacity="0.7" />
          <stop offset="1" stop-color="white" stop-opacity="0" />
        </linearGradient>
      </defs>
    </svg>
  )
}
